const data = $input.first()?.json || {};
const unscored = Array.isArray(data.unscored_offers) ? data.unscored_offers : [];

if (unscored.length === 0) {
  return [{ json: { hasUnscored: false, scores: [] } }];
}

const compactOffers = unscored.map((o) => ({
  id: o.id,
  contrat: o.type_contrat,
  zone: o.zone,
  ville: o.ville,
  trajet: o.trajet_tranche,
  entreprise: o.entreprise_nom,
  taille: o.taille_categorie,
  activite_connue: (o.entreprise_resume || o.libelle_naf || '').slice(0, 220),
  titre: o.titre,
  description: (o.description || '').slice(0, 900),
}));

const prompt = [
  "Tu es l'assistant carriere d'Ethan, etudiant en 1re annee d'ecole d'ingenieur informatique.",
  "Profil cible : stage de fin d'annee ete 2027 OU alternance de 2 ans (septembre 2027 -> 2029) autour de Loperhet/Brest, Lannion ou Caen.",
  'Priorites techniques :',
  '1. TRES HAUTE PRIORITE (80-100) : Cybersecurite (SOC, pentest, DevSecOps, SecOps, defense, cyber maritime/reseau), Intelligence Artificielle / ML / Data Engineering, et Systemes & Reseaux / Infra / Cloud / Linux.',
  '2. PERTINENT (60-79) : Developpement logiciel, DevOps, architecture SI, R&D tech — surtout dans les grands groupes/ETI (Thales, Naval Group, Nokia, Orange, Arkea, Sopra Steria, Capgemini, NXP, Exail, Ekinops, Ifremer, CNRS...).',
  '3. MOYEN / FAIBLE (30-54) : Systemes embarques ou electronique pure sans volet cyber/IA/reseau, ou support niveau 1 peu formateur.',
  '4. HORS SUJET (0-29) : Metier non informatique, CDI senior exigeant 3+ ans d experience sans mention stage/alternance, domaine commercial pur.',
  '',
  'Pour CHAQUE offre ci-dessous, retourne UNIQUEMENT un JSON valide : {"scores": [{"id": <entier>, "score_ia": <0-100>, "domaine_ia": "<Cyber|IA|SysRes|Dev|Tech|Embarque|Hors-sujet>", "resume_ia": "<2 phrases courtes en francais sur les missions, la stack et pourquoi ca matche>", "entreprise_resume": "<1 phrase claire en francais expliquant ce que fait reellement cette entreprise>"}]}.',
  '',
  JSON.stringify(compactOffers),
].join('\n');

const geminiBody = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: {
    responseMimeType: 'application/json',
    temperature: 0.2,
    maxOutputTokens: 8192,
    thinkingConfig: { thinkingBudget: 256 },
  },
};

return [{ json: { hasUnscored: true, geminiBody } }];

const resp = $input.first()?.json || {};
const parts = resp?.candidates?.[0]?.content?.parts || [];
const rawText = parts
  .filter((p) => !p.thought && typeof p.text === 'string')
  .map((p) => p.text)
  .join('')
  .trim();

if (!rawText) {
  throw new Error('Reponse Gemini scoring vide : ' + JSON.stringify(resp).slice(0, 400));
}

const cleanJson = rawText
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const parsed = JSON.parse(cleanJson);
const scores = Array.isArray(parsed?.scores) ? parsed.scores : [];
return [{ json: { scores } }];

const data = $input.first()?.json || {};
const pending = Array.isArray(data.pending_to_notify) ? data.pending_to_notify : [];

if (pending.length === 0) {
  return [];
}

const zoneLabel = {
  loperhet: 'Loperhet / Brest',
  lannion: 'Lannion',
  caen: 'Caen',
};

const embeds = pending.map((o) => {
  const isStage = String(o.type_contrat || '').toLowerCase() === 'stage';
  const badge = isStage ? 'STAGE ETE 2027' : 'ALTERNANCE 2 ANS';
  const color = isStage ? 3447003 : 5793266;
  const zTxt = zoneLabel[o.zone] || o.zone || 'Zone cible';
  const loc = [o.ville, zTxt, o.trajet_tranche].filter(Boolean).join(' · ');
  const act = o.entreprise_resume ? `\n**Entreprise :** ${String(o.entreprise_resume).slice(0, 220)}` : '';
  const sum = o.resume_ia ? String(o.resume_ia).slice(0, 320) : 'Nouvelle offre detectee correspondant a ton profil.';

  return {
    title: `[${badge}] ${String(o.titre || '').slice(0, 180)}`,
    url: o.url_directe,
    color,
    description: `**${o.entreprise_nom}**${o.taille_categorie ? ` (${o.taille_categorie})` : ''} — **${o.score_ia}/100** (${o.domaine_ia || 'Tech'})\n${loc}${act}\n\n${sum}\n\n[Ouvrir l'offre directe](${o.url_directe}) · [Suivre sur Career Radar](https://carriere.homelab)`,
  };
});

const batches = [];
for (let i = 0; i < embeds.length; i += 5) {
  const sliceEmbeds = embeds.slice(i, i + 5);
  const sliceIds = pending.slice(i, i + 5).map((o) => o.id);
  const header = i === 0
    ? `🎯 **Radar Stage & Alternance — ${pending.length} nouvelle(s) offre(s) pertinente(s)** (<https://carriere.homelab>)`
    : '📌 **Suite des offres détectées**';
  batches.push({
    json: {
      offerIds: sliceIds,
      payload: {
        content: header,
        embeds: sliceEmbeds,
      },
    },
  });
}

return batches;

const items = $('Formater Embeds Discord').all();
const ids = items.flatMap((it) => Array.isArray(it.json?.offerIds) ? it.json.offerIds : []);
if (ids.length === 0) {
  return [];
}
return [{ json: { ids } }];
